window.__saqPaperQuestions("2025-2-pah",[{"number":1,"title":"","stemText":"A 68 year old man has presented to the emergency department with sudden onset of severe pain in\nhis right leg for the past 2 hours.\nYou are considering the diagnosis of an acutely ischaemic lower limb.","parts":[{"id":"p1","label":"Part 1","prompt":"State 2 methods of confirming critical limb ischemia at the bedside. (2 marks)\nYour assessment is consistent with an acutely ischaemic lower limb."},{"id":"p2","label":"Part 2","prompt":"List 4 potential causes of this problem. (4 marks)"},{"id":"p3","label":"Part 3","prompt":"List and justify 3 investigations you would perform. (3 marks)"},{"id":"p4","label":"Part 4","prompt":"State 3 components of your management of this patient. (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">ABI – severe ischaemia &lt;0.4</div><div class=\"answer-line\">Doppler ultrasound – absent pulse on doppler</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Embolism from AF</div><div class=\"answer-line\">Thrombosis on pre-existing atherosclerosis</div><div class=\"answer-line\">Vascular graft or stent occlusion if patient has known PVD</div><div class=\"answer-line\">Aortic dissection with limb branch involvement</div><div class=\"answer-line\">Iatrogenic or procedural injury – recent angiography leading to thrombosis of dissection</div><div class=\"answer-line\">AAA embolization or thrombosis</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\"><strong>CT angio of limb</strong> – define extent and location for operative planning</div><div class=\"answer-line\">ECG – assess for AF as embolic cause</div><div class=\"answer-line\">Renal function – assess for renal impairment prior to IV contrast</div></section><section class=\"answer-part\"><h5>Part 4</h5><div class=\"answer-line\"><strong>Anticoagulation</strong> – IV heparin bolus + infusion</div><div class=\"answer-line\">IV analgesia – something reasonable here (not oral)</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":2,"title":"","stemText":"A 22 year old man has presented to the ED with palpitations and dizziness.\nHis ECG is provided below.","parts":[{"id":"p1","label":"Part 1","prompt":"Provide your interpretation, including supportive features from the ECG. (5 marks)"},{"id":"p2","label":"Part 2","prompt":"State 3 treatment options for this problem. (3 marks)"},{"id":"p3","label":"Part 3","prompt":"List 3 drugs that would be contra-indicated in this situation. (3 marks)"}],"propPages":["asset:img764bbf2dff7ae49be0"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">irregularly irregular</div><div class=\"answer-line\">Wide QRS complexes</div><div class=\"answer-line\">Very rapid ventricular response – rate 220</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Flecainide 2mg/kg IV</div><div class=\"answer-line\">Amiodarone 5mg/kg load IV</div><div class=\"answer-line\">procainamide</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">Adenosine</div><div class=\"answer-line\">Beta-blockers eg metoprolol</div><div class=\"answer-line\">Non-dihydropyridine Ca channel blockers eg verapamil</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":3,"title":"","stemText":"A 6 year old girl has presented via ambulance with an acute exacerbation of asthma.\nThe child has received 12 puffs of salbutamol MDI via a spacer en route and has been commenced\n• n oxygen via Hudson Mask.\nShe is pale with markedly increased work of breathing and has a quiet chest on auscultation.\nHer vital signs are:\n\nHR\n160 /min\n\nRR\n/min O2 sats 88% 6 L/min O2 via Hudson mask\n\nBP\n95/60 mmHg\n\nTemp\n36.5 degrees\n\nWeight\nkg","parts":[{"id":"p1","label":"Part 1","prompt":"State 6 steps in your initial management. (6 marks)\nThe child has deteriorated despite your initial management and you have determined that intubation is required."},{"id":"p2","label":"Part 2","prompt":"State 5 modifications to your standard rapid sequence intubation that you would make in\nthis situation. Provide rationale for each. (5 marks) Shortly after intubation, the child’s blood pressure has dropped to 65/40 mmHg."},{"id":"p3","label":"Part 3","prompt":"List 6 potential causes for the child’s hypotension. State how you will manage each cause. (6 marks) Cause Management"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\"><strong>Escalation of oxygenation therapy</strong> – 100% FiO2 HFNP 2L/kg flow rate</div><div class=\"answer-line\"><strong>Continuous 5mg salbutamol nebs </strong></div><div class=\"answer-line\">Continuous or 3x 500mcg ipratropium nebs every 20 mins</div><div class=\"answer-line\">IV hydrocortisone – 4mg/kg</div><div class=\"answer-line\">IV mag – 0.2mmol/kg (max 10 mmol) over 20 mins</div><div class=\"answer-line\">IM adrenaline 10mcg/kg or something similar eg IV bolus salbutamol 10mcg/kg</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Optimise Pre-oxygenation with high flow – aim to avoid hypoxia with induction apnoea</td><td>apnoeic oxygenation – 15L O2 via nasal cannulae – prolong safe period of apnoea / avoid hypoxia</td></tr><tr><td>bag through apnoea – avoid hypoxia / hypercapnoea</td><td>ketamine as induction agent – 2mg/kg - bronchodilator</td></tr><tr><td>IV fluid bolus prior to intubation anticipating post induction hypotension</td><td>Induce sitting up – maximise patient’s own respiratory effort as long as possible</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\"><strong>Dynamic hyperinflation</strong> – disconnect vent, allow passive exhalation, reduce rate/PEEP</div><div class=\"answer-line\"><strong>Tension ptx</strong> – ICC insertion</div><div class=\"answer-line\">Medication related vasodilation – IV fluids, norad</div><div class=\"answer-line\">Hypoxia from R main bronchus intubation – withdraw tube and re-xray</div><div class=\"answer-line\">Hypoxia from Blocked tube – in-line suction to dislodge mucous</div><div class=\"answer-line\">Anaphylaxis from drugs – IM/IV adrenaline with doses</div><div class=\"answer-line\">Sepsis – fluids, Abs, norad</div><div class=\"answer-line\">Reduced venous return from PEEP – reduce PEEP, IV fluids</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":4,"title":"","stemText":"You are reviewing a study that investigates whether the early administration of IV pantoprazole reduces hospital length of stay in adults presenting to the ED with an upper GI bleed. The researchers conducted a single-centre, prospective trial over 12 months.","parts":[{"id":"p1","label":"Part 1","prompt":"What is the most appropriate study design for this research? Provide a justification for your response. (3 marks)"},{"id":"p2","label":"Part 2","prompt":"Define the following terms used in clinical research. (4 marks) Randomisation Blinding Validity Confounding variable"},{"id":"p3","label":"Part 3","prompt":"List 3 types of bias that could affect the validity of the described study and explain how each could be minimised. (3 marks) Type of bias How to minimise The researchers reported the mean and standard deviation of hospital length of stay."},{"id":"p4","label":"Part 4","prompt":"What criteria must be met for these to be appropriate descriptive statistics? (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">RCT</td></tr><tr><td>-</td><td>Allows comparison of outcomes between intervention (IV pantoprazole) group and</td></tr><tr><td colspan=\"2\">control group</td></tr><tr><td>-</td><td>Randomisation helps reduce bias</td></tr><tr><td>-</td><td>Prospective nature ensures standardised data collection</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Randomisation – process of allocating participants to different groups using chance alone</div><div class=\"answer-line\">Blinding – withholding group assignment from participants, care givers or outcome assessors</div><div class=\"answer-line\">Validity – how well the results among the study participants represent true findings among similar</div><div class=\"answer-line\">individuals outside of the study</div><div class=\"answer-line\">Confounding variable – a variable not directly studied that may independently influence the</div><div class=\"answer-line\">outcome</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">Observer bias – data collection is less objective due to knowledge of the subject – minimise by</div><div class=\"answer-line\">blinding the staff to intervention or outcome</div><div class=\"answer-line\">Performance bias – differences in care provided to groups beyond the intervention itself –</div><div class=\"answer-line\">minimised by blinding treating clinicians and standardising co-interventions</div><div class=\"answer-line\">Selection bias – sample used in study differs significantly from the larger population researchers</div><div class=\"answer-line\">want to draw conclusions about – minimised by randomisation and setting careful sampling criteria</div><div class=\"answer-line\">Attrition bias – systematic differences between comparison groups in withdrawals/exclusions of</div><div class=\"answer-line\">participants in result of study minimised by ensuring follow-up is complete and equal between both</div><div class=\"answer-line\">groups</div></section><section class=\"answer-part\"><h5>Part 4</h5><div class=\"answer-line\">Data must be normally distributed</div><div class=\"answer-line\">No significant outliers</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":5,"title":"","stemText":"A 6 year old boy has presented to the ED after falling out of a tree.\nHe has an obviously deformed forearm with a wound over the deformity. There are no other injuries. His x-ray is provided below.","parts":[{"id":"p1","label":"Part 1","prompt":"Describe and interpret the x-ray. (3 marks)"},{"id":"p2","label":"Part 2","prompt":"State 4 components of your examination of this child, related to the injury shown.\n(4 marks)"},{"id":"p3","label":"Part 3","prompt":"State 5 components of your management of this child. (5 marks)"}],"propPages":["asset:img5e0e70969a5686bfc1"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Monteggia fracture / dislocation</div><div class=\"answer-line\">Mid-shaft ulnar fracture – displaced, angulated</div><div class=\"answer-line\">Radial head dislocated<strong> </strong></div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\"><strong>Distal perfusion</strong> - radial and ulnar artery pulses</div><div class=\"answer-line\">Radial nerve involvement – PIN injury – finger extension, snuffbox sensation</div><div class=\"answer-line\">Median nerve – thumb abduction, sensation thenar eminence</div><div class=\"answer-line\">Ulnar nerve – finger abduction, sensation little finger</div><div class=\"answer-line\">Wound assessment for degree of defect and contamination</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\"><strong>Analgesia</strong> – IV with doses</div><div class=\"answer-line\">Procedural sedation for plaster (also accept reduction)</div><div class=\"answer-line\">Immobilisation in above elbow backslab</div><div class=\"answer-line\"><strong>IV antibiotics</strong> - kefzol</div><div class=\"answer-line\"><strong>Ortho referral for surgical fixation</strong> and formal washout in theatre</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":6,"title":"","stemText":"A 62 year old woman has presented to the ED with severe left eye pain after going to the movies. A clinical photograph is provided below.","parts":[{"id":"p1","label":"Part 1","prompt":"Describe and interpret the photograph. (3 marks)"},{"id":"p2","label":"Part 2","prompt":"List 2 key features of your assessment, including the expected findings. (2 marks)"},{"id":"p3","label":"Part 3","prompt":"State 6 potential components of the management of this patient. (6 marks)"}],"propPages":["asset:img62b9ac1c18c04037cb"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Conjunctival injection</div><div class=\"answer-line\">Mid-dilated pupil</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">VA markedly reduced</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">Topical beta blockers – e.g. timolol</div><div class=\"answer-line\">Topical alpha agonists – e.g. brimonidine (alphagan), apraclonidine</div><div class=\"answer-line\">IV acetazolamide</div><div class=\"answer-line\">Antiemetics</div><div class=\"answer-line\">Analgesia</div><div class=\"answer-line\">Urgent ophthalmology referral for laser iridotomy</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":7,"title":"","stemText":"An 82 year old man has presented with fever, dyspnoea, chest pain and a productive cough. He was discharged from your hospital 5 days ago after a week long hospital admission with influenza A. He is on long-term steroids for rheumatoid arthritis. His chest x-ray is shown below.","parts":[{"id":"p1","label":"Part 1","prompt":"Provide a clinical interpretation for this CXR, supported by the radiographic abnormalities. (4 marks)\nHis vital signs are:\n\nHR\n120 /min\n\nBP\n85/60 mmHg O2 sats 85% 6 L/min O2 via Hudson mask\n\nRR\n/min\n\nTemp\n38.8 degrees"},{"id":"p2","label":"Part 2","prompt":"Provide your antibiotic strategy with rationale. (3 marks)"},{"id":"p3","label":"Part 3","prompt":"State 4 other components of your management. (4 marks)\nDespite your management, the patient has continued to deteriorate. He cannot communicate due to severe distress."},{"id":"p4","label":"Part 4","prompt":"State 6 key components of the discussion you will have with the patient’s family regarding the patient’s current situation. (6 marks)"}],"propPages":["asset:img14d249d35d074c1138"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Multi-lobar pneumonia</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Likely staph aureus</div><div class=\"answer-line\">Bilateral patchy consolidation</div><div class=\"answer-line\">Some areas confluent</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">IV piptaz 4.5g – broad spectrum for HAP – staph, gram -ves (E coli, Kleb), Pseudomonas</div><div class=\"answer-line\"><strong>IV vancomycin</strong> 30mg/kg load – MRSA</div><div class=\"answer-line\">(rationale is the third mark)</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\"><strong>Escalate oxygen therapy</strong> – 15L NRBM aiming sats &gt;92%</div><div class=\"answer-line\"><strong>IV fluid bolus</strong> – 1L N/S stat</div><div class=\"answer-line\">IV hydrocortisone 100-200mg</div><div class=\"answer-line\">Analgesia – something reasonable</div></section><section class=\"answer-part\"><h5>Part 4</h5><div class=\"answer-line\">Summary of clinical events</div><div class=\"answer-line\">Predicted clinical trajectory / poor prognosis</div><div class=\"answer-line\">Clarify co-morbidities and medical background</div><div class=\"answer-line\">Clarify functional status and quality of life</div><div class=\"answer-line\">Documented wishes of the patient – formal ARP, AHD etc</div><div class=\"answer-line\">Establish NOK / substitute decision maker</div><div class=\"answer-line\">Offer realistic options – ward based therapies, comfort care</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":8,"title":"","stemText":"A 42 year old woman has presented with headache and confusion.\nHer vital signs are:\n\nHR\n/min\n\nBP\n240/130 mmHg\n\nRR\n/min O2 sats 99% room air\nTemperature 37.3\ndegrees You are considering the diagnosis of hypertensive encephalopathy.","parts":[{"id":"p1","label":"Part 1","prompt":"List 4 differential diagnoses. Provide a key feature of your history for each.\n(4 marks) Differential diagnosis Feature of history"},{"id":"p2","label":"Part 2","prompt":"List and justify 4 investigations you would perform. (4 marks)\nFollowing your assessment, you have made the provisional diagnosis of hypertensive encephalopathy."},{"id":"p3","label":"Part 3","prompt":"Provide your targets for management of her blood pressure. (2 marks)"},{"id":"p4","label":"Part 4","prompt":"List 2 medications you might use to manage her blood pressure. Provide the mechanism\n• f action for each. (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Meningoencephalitis – fever</td><td>Pre-eclampsia – missed periods</td></tr><tr><td>SAH – thunderclap headache</td><td>Tox – amphetamines, cocaine ingestion</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">CT head – exclude SAH, angio for aneurysm, other SOL</div><div class=\"answer-line\">HCG – exclude pregnancy / pregnancy related causes hypertension</div><div class=\"answer-line\">Renal function – looking for renal failure due to hypertension</div><div class=\"answer-line\">ECG – features of LVH</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">Reduce by 10% first hour, maximum reduction of 25% within first 24 hours</div></section><section class=\"answer-part\"><h5>Part 4</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Labetalol – alpha and beta blocker – vasodilator and negative inotrope/chronotrope</td><td>Hydralazine – alpha blockade - vasodilator</td></tr><tr><td>Others OK</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":9,"title":"","stemText":"A 34 year old man has been taken to ED after ingesting an unknown quantity of organophosphate pesticide.","parts":[{"id":"p1","label":"Part 1","prompt":"List 6 features of organophosphate toxicity. (6 marks)\nThe patient has significant organophosphate toxicity."},{"id":"p2","label":"Part 2","prompt":"State the main component of your management. (3 marks)"},{"id":"p3","label":"Part 3","prompt":"State 3 other potential components of your management. Include the indication for its\nuse. (3 marks)\nPAH 2025.2 trial SAQ paper\nPART 2\nQuestions 10 - 18\n1 hour"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Autonomic</div><div class=\"answer-line\">-&gt;Cholinergic (muscarinic) - sweating, miosis<strong>, bradycardia, hypotension</strong>, salivation,</div><div class=\"answer-line\">lacrimation, diarrhoea, urinary frequency, bronchorrhea, bronchoconstriction</div><div class=\"answer-line\">-&gt;Cholinergic (nicotinic) – muscle fasciculations, neuromuscular paralysis</div><div class=\"answer-line\">Resp – respiratory depression, bronchorrhea, bronchoconstriction <strong>(one of these necessary)</strong></div><div class=\"answer-line\">Cardiovascular – bradycardia, arrhythmia, refractory shock</div><div class=\"answer-line\">CNS – seizure, confusion, coma</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">1.2mg IV – double every 3-5 mins</div><div class=\"answer-line\">Endpoints – clear chest (no wheeze), HR &gt;80, SBP &gt;80</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">Decontamination – wash skin – if there has been dermal exposure</div><div class=\"answer-line\">Intubation – if unable to maintain effective breathing / hypoxic despite O2</div><div class=\"answer-line\">IV fluids N/S – if hypotension – aim BP &gt;90 systolic</div><div class=\"answer-line\">IV adrenaline – in addition to atropine if hypotension / bradycardia persistent</div><div class=\"answer-line\">? Pralidoxime if refractory to atropine – not used anymore really</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":10,"title":"","stemText":"A 16 year old girl has been brought to the ED by her parents. They are concerned about her restrictive eating behaviours and significant weight loss.","parts":[{"id":"p1","label":"Part 1","prompt":"List 3 features of your examination that would require the patient to be admitted for re-\nfeeding. (3 marks)"},{"id":"p2","label":"Part 2","prompt":"List 3 investigative findings that would require the patient to be admitted for re-feeding. (3 marks) While having an ECG recorded, the patient suddenly became unconscious and a duress alarm was activated. The ECG is provided below."},{"id":"p3","label":"Part 3","prompt":"Describe and interpret the ECG. (5 marks)"},{"id":"p4","label":"Part 4","prompt":"State 6 treatment steps you might employ. Provide the clinical indication for each.\n(6 marks) Treatment step Clinical indication"}],"propPages":["asset:img45bd9d7c2d9fc1097c"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">First half is SR with long QT</div><div class=\"answer-line\">Then R on T</div><div class=\"answer-line\"><strong>then Torsades de Pointes</strong></div><div class=\"answer-line\">-</div><div class=\"answer-line\">Wide complex tachycardia with changing axis</div><div class=\"answer-line\">4.</div><div class=\"answer-line\"><strong>DCCV / defibrillation 200J – for cardioversion out of torsades </strong></div><div class=\"answer-line\"><strong>IV MgSO4 10mmol</strong> – to prevent further Torsades / treat long QT</div><div class=\"answer-line\">IV KCl 10mmol if potassium is low – treat long QT</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">1. 2.</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">Electrical 120/min</div><div class=\"answer-line\">Replace Ca / Po4 if low</div><div class=\"answer-line\">IV dextrose – appropriate dose if hypoglycaemia</div></section><section class=\"answer-part\"><h5>Part 4</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Others OK</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":11,"title":"","stemText":"A 6 year old boy has presented with a sore throat of 2 days duration.","parts":[{"id":"p1","label":"Part 1","prompt":"List 4 potential diagnoses. For each, provide a discriminatory finding from history or\nexamination. (4 marks) Diagnosis Finding from history or examination"},{"id":"p2","label":"Part 2","prompt":"List 4 potential investigations you might order. Give the clinical utility for each. (4 marks) Investigation Clinical utility The child was discharged. He has represented 12 hours later with a rash."},{"id":"p3","label":"Part 3","prompt":"List 4 potential causes of his rash. Provide a description of the appearance of the rash for each cause. (4 marks) Cause of rash Description of appearance"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Bacterial Tonsillitis – bilateral red, purulent tonsils</td><td>EBV / glandular fever – contact with another person with EBV</td></tr><tr><td>Quinsy – unilateral soft palate swelling</td><td>Epiglottitis – unimmunised, septic, drooling, stridor</td></tr><tr><td>Retropharyngeal abscess – septic, can’t swallow, stiff neck</td><td>Others</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Throat swab – identify strep where diagnosis is uncertain bacterial vs viral</td><td>BC – if septic to identify organism / modify Ab Rx in coming days</td></tr><tr><td>Lateral soft tissue x-ray – looking for pre-vertebral soft tissue swelling in retropharyngeal abscess</td><td>Monospot / EBV serology – diagnose EBV – may not require Abs</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Drug allergy – urticarial – wheal / flare</td><td>EM – target lesions</td></tr><tr><td>Scarlet fever – red, sandpaper like feel</td><td>Meningococcal sepsis – petechial / purpuric rash</td></tr><tr><td>Others</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":12,"title":"","stemText":"A 65 year old woman has presented with difficulty breathing. Your assessment is consistent with an acute infective exacerbation of her emphysema. Her arterial blood gas is provided below.\n\nFiO2\n0.5\n\npH\n7.09 (7.35 - 7.45)\n\npCO2\n104 mmHg (35 - 45)\n\npO2\nmmHg (80 - 100)\n\nHCO3\nmmol/L (20 - 29)\n\nNa\n143 mmol/L (135 - 145)\n\nK\n4.7 mmol/L (3.5 - 5.2)\n\nCl\n100 mmol/L (95 - 110)","parts":[{"id":"p1","label":"Part 1","prompt":"Interpret the arterial blood gas. (4 marks) Her initial vitals are:\n\nGCS\nE3 V4 M5 Pulse 110 /min\n\nBP\n125/70 mmHg\n\nRR\n/min\n\nTemp\n38.0 degrees You have elected to place her on non-invasive ventilation (NIV)."},{"id":"p2","label":"Part 2","prompt":"State 4 other components of your management. (4 marks)\nThe patient has been on NIV for several hours."},{"id":"p3","label":"Part 3","prompt":"List 4 changes you might make to her NIV settings. Explain the indication for each.\n(4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Raised A-a gradient</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\"><strong>Salbutamol </strong>12 puffs inhaled – can be continuous initially also accept burst</div><div class=\"answer-line\">Ipratropium 500mcg burst/neb</div><div class=\"answer-line\">IV hydrocortisone 100-200mg</div><div class=\"answer-line\">Antibiotics – IV benpen 2.4g, oral doxy 100mg (or something similar) also accept regimes for more</div><div class=\"answer-line\">severe pneumonia</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Reduce FiO2</td><td></td></tr><tr><td>-</td><td>Where O2 sats &gt;92% so not to block hypoxic drive</td></tr><tr><td>Increase PEEP</td><td></td></tr><tr><td>-</td><td>Where low O2 sats, in combination with increasing FiO2</td></tr><tr><td>Increase iPAP</td><td></td></tr><tr><td>-</td><td>To increase TV where CO2 is not falling</td></tr><tr><td>Increase backup rate</td><td></td></tr><tr><td>– where pt is tiring and RR too slow to maintain minute volume required to clear CO2</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":13,"title":"","stemText":"A 55 year old man has presented with severe abdominal pain for the last 6 hours.\nHis past medical history includes atrial fibrillation, hypertension and type 2 diabetes mellitus.","parts":[{"id":"p1","label":"Part 1","prompt":"List 6 differential diagnoses. For each, provide the discriminatory feature/s of your\nabdominal examination. (6 marks) Diagnosis Feature/s of abdominal examination Two slices of his CT scan are provided below."},{"id":"p2","label":"Part 2","prompt":"Describe and interpret the images. (6 marks)"}],"propPages":["asset:imgba8ecd6b03e686c0c3","asset:imgafc5962c33137b820f"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Appendicitis – RLQ peritonism</td><td>Cholecystitis – RUQ peritonism, Murphy’s sign positive</td></tr><tr><td>Ruptured AAA – pulsatile epigastric mass</td><td>Ischaemic bowel – initially soft with not many signs then generalised peritonism</td></tr><tr><td>Diverticulitis – LLQ peritonism</td><td>Bowel obstruction – distended, tympanic PN, scars from previous surgery – adhesions</td></tr><tr><td>others</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Ischemic bowel with perforation:</div><div class=\"answer-line\">- pneumoperitoneum with falciform ligament illustrated</div><div class=\"answer-line\">- intramural bowel gas</div><div class=\"answer-line\">- portal venous gas and gas in SMV</div><div class=\"answer-line\">- non-enhancing bowel</div><div class=\"answer-line\">- peritoneal free fluid</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":14,"title":"","stemText":"A 27 year old man has presented after falling on to his face while drunk.\nHe has peri-orbital swelling and jaw pain. There are no other injuries.","parts":[{"id":"p1","label":"Part 1","prompt":"List 5 features of your eye examination. Provide the relevance of each. (5 marks)\nFeature of eye examination Relevance His orthopantomogram (OPG) is provided below."},{"id":"p2","label":"Part 2","prompt":"Describe and interpret the OPG. (3 marks)"},{"id":"p3","label":"Part 3","prompt":"State 3 components of your management of this injury. (3 marks)"}],"propPages":["asset:img900c04c898b6025e8a"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\"><strong>VA</strong> – determine whether visual axis injury / severity of threat to eyesight</div><div class=\"answer-line\">Eye movements – upward gaze restriction in inferior rectus entrapment with orbital floor #</div><div class=\"answer-line\">Pupils – traumatic mydriasis</div><div class=\"answer-line\">IOP – high pressures might reflect orbital compartment syndrome and need for canthotomy</div><div class=\"answer-line\">Slit lamp exam anterior chamber – exclude hyphaema</div><div class=\"answer-line\">Fluorescein stain looking for corneal abrasion</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\"># bilateral mandibular condyle, angulated</div><div class=\"answer-line\"># right mandibular body extending to root of lateral incisor (4,2)</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Hence a compound injury</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">Max-fax referral</div><div class=\"answer-line\">Analgesia – appropriate</div><div class=\"answer-line\">IV Abs – eg ampicillin 1g, metronidazole 500mg</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":15,"title":"","stemText":"After presenting in advanced labour, a woman has delivered a child in the department. The\npregnancy was 34 weeks duration.\nYou have been allocated to manage the baby.","parts":[{"id":"p1","label":"Part 1","prompt":"List 3 maternal risk factors for the requirement of neonatal resuscitation. (3 marks)"},{"id":"p2","label":"Part 2","prompt":"List the 3 initial assessment features of the child that will inform your management.\n(3 marks) The child requires resuscitation."},{"id":"p3","label":"Part 3","prompt":"State 6 treatment measures you might institute. Provide the indication for each.\n(6 marks) Treatment measure Indication"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\"><strong>(9/12) </strong></div><div class=\"answer-line\">1.</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">HR</div><div class=\"answer-line\">tone</div><div class=\"answer-line\">Resp effort</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Assisted ventilation – BVM – where no breathing after initial stimulation</td><td>CPAP – where newborn has begun respiratory effort but is ineffective</td></tr><tr><td>CPR – where HR less than 60 after initial 30s of BVM</td><td>Intubation – where BVM has been unsuccessful or prolonged (ongoing HR &lt;60)</td></tr><tr><td>IV adrenaline 10mcg/kg – ongoing bradycardia despite initial period CPR</td><td>IV N/S 10ml/kg/ blood/Abs/dextrose/others with suitable indication</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":16,"title":"","stemText":"A 45 year old woman has presented with severe menorrhagia. She has had increasingly heavy\nmenstrual bleeding over the last 12 months. She is not pregnant.","parts":[{"id":"p1","label":"Part 1","prompt":"List 5 features of your history and examination, including the relevance of each. (5 marks)"},{"id":"p2","label":"Part 2","prompt":"List 4 investigations you might perform, including the justification for each. (4 marks)\nYour provisional diagnosis is dysfunctional uterine bleeding."},{"id":"p3","label":"Part 3","prompt":"State 3 treatment options for this patient. (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">How much blood loss – how many pads/clots, duration bleeding  – define blood loss, need for fluid</div><div class=\"answer-line\">Vital signs - tachycardia/hypotension requiring resuscitation</div><div class=\"answer-line\">?known fibroids – cause</div><div class=\"answer-line\">Hx coagulopathy/anticoagulation- cause heavy bleeding</div><div class=\"answer-line\">Last pap smear – likelihood of cervical Ca causing bleeding</div><div class=\"answer-line\">Speculum examination ?cervical lesions</div><div class=\"answer-line\">Bimanual PV exam – fibroids, bulky uterus ?Ca</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>Hb – exclude anaemia requiring transfusion</td><td>TFTS – hypothyroidism causing menorrhagia</td></tr><tr><td>Coag – if on warfarin define degree coagulopathy</td><td>Plt – thrombocytopenia cause of coagulopathy</td></tr><tr><td>Accept uterine USS – exclude endometrial thickening and possible Ca</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">OCP</div><div class=\"answer-line\">Norethisterone 5mg tds</div><div class=\"answer-line\">Tranexamic acid 1g tds 3-5 days</div><div class=\"answer-line\">NSAIDs</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":17,"title":"","stemText":"A 5 year old boy has been brought to the ED with a fever and vomiting.\nHis full blood count (FBC) is provided below.\n\nHb\ng/dL (100 - 150)\n\nWCC\n45.8 *10^9/L (5 - 15) Plt *10^9/L (150 - 450)","parts":[{"id":"p1","label":"Part 1","prompt":"Describe and interpret the FBC. (3 marks)"},{"id":"p2","label":"Part 2","prompt":"List 4 features of your history, including the relevance of each. (4 marks)"},{"id":"p3","label":"Part 3","prompt":"List 4 features of your examination, including the relevance of each. (4 marks)\nFollowing your assessment, you intend to treat the child with antibiotics to cover sepsis of uncertain\n• rigin."},{"id":"p4","label":"Part 4","prompt":"State 6 factors you would consider in deciding which antibiotics to use. (6 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Leukaemoid FBC</div><div class=\"answer-line\">Anaemia and thrombocytopenia due to marrow infiltration</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">B symptoms to suggest leukaemia</div><div class=\"answer-line\">Bleeding complaints – to help explain anaemia / might need specific intervention</div><div class=\"answer-line\">Bruising/bleeding gums etc with low plts</div><div class=\"answer-line\">Assessment of fever / sepsis – symptoms eg cough, abdo pain</div><div class=\"answer-line\">Other organ involvement – SOB / headaches / decreased urine output</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\"><strong>Vital signs </strong>– exclude sepsis/shock concurrent with leukaemia</div><div class=\"answer-line\">Splenomegaly – common due to ALL</div><div class=\"answer-line\">Resp exam – exclude leukostasis causing lung injury</div><div class=\"answer-line\">Bleeding sites that might need attention to stop bleeding</div><div class=\"answer-line\">Lots of others</div></section><section class=\"answer-part\"><h5>Part 4</h5><div class=\"answer-line\">Local protocol for febrile oncology pts</div><div class=\"answer-line\">Known allergies – avoid these</div><div class=\"answer-line\">?shock present – more aggressive eg add vancomycin</div><div class=\"answer-line\">From a high prevalence MRSA group – add vancomycin</div><div class=\"answer-line\">Previous sensitivities – eg resistant E coli UTI</div><div class=\"answer-line\">Indwelling lines – add vanc</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":18,"title":"","stemText":"A 65 year old man has presented with a reduced level of consciousness.\nHe has a history of HIV infection.","parts":[{"id":"p1","label":"Part 1","prompt":"List 6 differential diagnoses for his reduced level of consciousness related to HIV infection. State the assessment finding (history, examination or investigation) that will confirm the presence of each. (12 marks) Differential diagnosis Confirmatory assessment finding\nPAH 2025.2 trial SAQ paper\nPART 3\nQuestions 19 - 27\n1 hour"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Toxoplasmosis – serology, ring enhancing lesions on CT</div><div class=\"answer-line\">HIV encephalitis – CSF with HIV RNA, no other pathology CT, CSF</div><div class=\"answer-line\">Cryptococcal meningitis – India ink stain CSF</div><div class=\"answer-line\">Cerebral lymphoma – lesions on CT scan</div><div class=\"answer-line\">TB meningitis – CSF with Mycobacterium</div><div class=\"answer-line\">HIV seroconversion meningitis – recent sexual contact with known HIV source, other tests negative</div><div class=\"answer-line\">Also accept PML, brain abscess, neurosyphilis, CMV encephalitis, HIV dementia</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":19,"title":"","stemText":"A 55 year old man has been brought to the Emergency Department after a head-on motor vehicle\naccident at 100km/hr. He was the restrained driver of one of the vehicles.\nHis chest x-ray is provided below.","parts":[{"id":"p1","label":"Part 1","prompt":"Interpret the x-ray, including the supportive radiographic findings. (5 marks) Pelvic x-ray and FAST scan are normal. There are no obvious limb injuries. His vitals signs are:\n\nGCS\nE3 V4 M5 Pulse 130 /min\n\nBP\n75/45 mmHg\n\nRR\n/min O2 sats 90% 15L O2 via non-rebreather"},{"id":"p2","label":"Part 2","prompt":"State 3 components of your initial management. (3 marks)\nCT angiography of the chest has revealed an arterial blush from a transection of an intercostal artery."},{"id":"p3","label":"Part 3","prompt":"State 2 options for definitive management of this injury. (2 marks)"}],"propPages":["asset:img04acce4e90f6fa1e7a"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Large/massive right haemothorax</td></tr><tr><td>-</td><td>Veiled right lung field</td></tr><tr><td>-</td><td>Large rim of radio-opaque blood outside lung edge</td></tr><tr><td>-</td><td>mediastinal shift to left (accept tension but not essential)</td></tr><tr><td colspan=\"2\">rib fracture right 4-6 ribs (at least)</td></tr><tr><td>-</td><td>asymmetrical / interrupted cortex ribs</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Intubation – details</div><div class=\"answer-line\">Right ICC – some details</div><div class=\"answer-line\">Blood o neg with end-points</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">OR</div><div class=\"answer-line\">IR</div><div class=\"answer-line\">with details</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":20,"title":"","stemText":"An 18 month old girl has been brought to the ED following a shaking episode at home.","parts":[{"id":"p1","label":"Part 1","prompt":"State 3 features of your history that would suggest seizure as the cause of her shaking.\n(3 marks) History is suggestive of a seizure."},{"id":"p2","label":"Part 2","prompt":"List 6 potential causes of her seizure. Provide a discriminatory feature of your assessment (history, examination or investigation) for each. (6 marks) Cause Assessment feature While in the ED, the child has had another seizure. The seizure is ongoing despite 2 doses of midazolam."},{"id":"p3","label":"Part 3","prompt":"List 3 medications, with doses, that you could administer to terminate the seizure.\n(3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Post-ictal period</div><div class=\"answer-line\">Previous seizures / known seizure disorder</div><div class=\"answer-line\">Loss continence / tongue biting etc</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td>Trauma – boggy haematoma, witnessed fall from table</td><td><strong>Hypoglycaemia</strong> – current illness with poor oral intake, diabetic with incorrect insulin admin</td></tr><tr><td>Dysrhythmias – prolonged QT - ECG</td><td>Intracranial brain abnormalities: brain tumour, stroke, AVM, idiopathic seizure – focal</td></tr><tr><td>neurological deficits</td><td>Drug exposure/ingestion – access to adult medications</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">Levetiracetam 40-60mg /kg</div><div class=\"answer-line\">Phenobarbitone 20mg/kg</div><div class=\"answer-line\">Valproate 20-40mg/kg</div><div class=\"answer-line\">Phenytoin 20mg/kg</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":21,"title":"","stemText":"A 58 year old man has presented with an 12 hour history of severe leg pain and fevers.\nHe has returned from a holiday at the beach where he was fishing and sailing. His medical history includes type 2 diabetes mellitus, hypertension and gout.\nHis vital signs are:\n\nGCS\nE4 V4 M6 Pulse 130 /min\n\nBP\n75/52 mmHg O2 sats 96% room air Temperature 38.9 degrees A clinical photograph is provided below.","parts":[{"id":"p1","label":"Part 1","prompt":"Describe and interpret the photograph. (4 marks)"},{"id":"p2","label":"Part 2","prompt":"List and justify 6 investigations you might perform. (6 marks)"},{"id":"p3","label":"Part 3","prompt":"State 4 antibiotics you might prescribe. Include the intended microbiological coverage for each. (4 marks)"},{"id":"p4","label":"Part 4","prompt":"State 4 other components of your management. (4 marks)"}],"propPages":["asset:imgd7ff178102412ac343"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Erythema lateral lower left leg</div><div class=\"answer-line\">Central area developing necrosis</div><div class=\"answer-line\">Several small abrasions dorsum foot</div><div class=\"answer-line\">With clinical picture, concern for necrotising fasciitis</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">VBG – assess degree hypoperfusion to guide resus</div><div class=\"answer-line\">Xray – look for gas to confirm diagnosis</div><div class=\"answer-line\">CT scan – look for gas to confirm diagnosis</div><div class=\"answer-line\">Wound swab – to identify bacteria / guide future AB rationalisation</div><div class=\"answer-line\">BC – same</div><div class=\"answer-line\">Renal function – look for AKI complicating sepsis – drug dosing guide</div><div class=\"answer-line\">Others will be OK</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Meropenem 1g – broad spectrum cover, Staph, Strep, gram neg, Clostridium</td><td>Vanc 25-30mg/kg – cover MRSA</td></tr><tr><td>Clindamycin 600mg – for Strep toxin</td><td>Ciprofloxacin 400mg – cover Vibrio vulnificus</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 4</h5><div class=\"answer-line\">Urgent surgical referral for debridement</div><div class=\"answer-line\">Analgesia eg IV morphine 2.5mg aliquots</div><div class=\"answer-line\">IV fluid – 1L N/S stat aiming for sys BP 100</div><div class=\"answer-line\">Something else – anti-emetic / manage complications / BSL management</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":22,"title":"","stemText":"You have been tasked with the management of a serious clinical incident in your Emergency Department. Recently, there was an unexpected death of a patient on the ambulance ramp while they were waiting to enter an acute bed of the ED.","parts":[{"id":"p1","label":"Part 1","prompt":"State 6 components of your management this incident. (6 marks)\nThe incident follows many complaints about the patient experience while waiting in the ambulance ramp area."},{"id":"p2","label":"Part 2","prompt":"List 6 potential steps that could be put in place to improve patient care while waiting in the ambulance ramp area. (6 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Clinical disclosure within 24hours of the incident + open disclosure to family</div><div class=\"answer-line\">Investigation: Discuss with staff present during incident (TL and in charge) and Review</div><div class=\"answer-line\">chart/documentation</div><div class=\"answer-line\">Liaise with Coroner as required</div><div class=\"answer-line\">Discuss at M&amp;M amongst peers</div><div class=\"answer-line\">Identify actions from M&amp;M</div><div class=\"answer-line\">Hospital legal/media to issue statement in response if required</div><div class=\"answer-line\">Follow up discussion with patient’s family</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Dedicated/ Regular communication with medical/nursing staff</div><div class=\"answer-line\">Regular vitals signs</div><div class=\"answer-line\">Meals if appropriate</div><div class=\"answer-line\">Administration regular meds</div><div class=\"answer-line\">Regular review by senior medical staff for deterioration</div><div class=\"answer-line\">Appropriate access to emergency alarms / O2/ suction etc</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":23,"title":"","stemText":"A 4 year old boy has been brought to the ED with diarrhoea and lethargy.\nHis vital signs are:\n\nGCS\nE3 V5 M6 - drowsy Pulse 120 /min\n\nBP\n115/70 mmHg O2 sats 96% room air Temperature 37.9 degrees Central cap refill 3-4 seconds His pathology results are provided below:\n\nHb\ng/L (115 - 160) Plt *10^9/L (150 - 450)\n\nWCC\n*10^9/L (3.5 - 11.0)\n\nNa\n149 mmol/L (135 - 145)\n\nK\n6.2 mmol/L (3.5 - 5.2)\n\nUrea\nmmol/L (2.7 - 7.8)\n\nCreatinine\n216 mmol/L (45 - 90)","parts":[{"id":"p1","label":"Part 1","prompt":"Interpret the results. Provide a cause for each of the abnormalities shown. (6 marks)"},{"id":"p2","label":"Part 2","prompt":"What is the most likely aetiology of this presentation? (1 mark)"},{"id":"p3","label":"Part 3","prompt":"List 4 other investigations you would perform, including a rationale for each. (4 marks)\nInvestigation Rationale"},{"id":"p4","label":"Part 4","prompt":"State 4 management priorities for this patient. (4 marks)"},{"id":"p5","label":"Part 5","prompt":"List 3 complications of this condition. (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Diagnosis is HUS</td><td>Anaemia due to haemolysis</td></tr><tr><td>Low plts due to consumption in small vessel thrombosis (like DIC)</td><td>High WBC due to inflammation / infection with gastro</td></tr><tr><td>High K due to renal failure / haemolysis</td><td>AKI (renal) due to microthrombi kidneys</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">E coli infection (Shiga toxin producing)</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>Blood film/smear – fragmented red cells/schistocytes to confirm MAHA</td><td>E.coli PCR / stool m/c/s</td></tr><tr><td>VBG – check glucose, lactate, acid/base status</td><td>Coagulations – exc DIC</td></tr><tr><td>Group &amp; save  - if needing transfusion</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 4</h5><div class=\"answer-line\">Packed red blood cell replacement</div><div class=\"answer-line\">IVF therapy – dehydration + maintenance</div><div class=\"answer-line\">Fluid balance with measured UO – may require dialysis if anuria</div><div class=\"answer-line\">Analgesia</div><div class=\"answer-line\">Anti-emetic</div><div class=\"answer-line\">Admission under paeds</div><div class=\"answer-line\">Notify public health</div><div class=\"answer-line\">Need specifics for each</div></section><section class=\"answer-part\"><h5>Part 5</h5><div class=\"answer-line\">Neuro – encephalopathy, confusion seizures</div><div class=\"answer-line\">Renal – oliguria/anuria, hyperK, HTN</div><div class=\"answer-line\">Cardiac – hypertension, hypertensive CM, myocarditis</div><div class=\"answer-line\">Resp – pulmonary oedema</div><div class=\"answer-line\">GI – pancreatitis, GI haemorrhage, cholestasis</div><div class=\"answer-line\">Haem - bleeding</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":24,"title":"","stemText":"A 45 year old woman has presented with abdominal pain, vomiting and jaundice.\nHer liver function tests are provided below. Bilirubin umol/L (<25) ALP 184 U/L (30 - 110) GGT 104 U/L (<90) ALT 4800 U/L (<65) AST 4220 U/L (<50) Albumin g/L (32 - 50)\n\nINR\n3.2 (0.9 - 1.3)","parts":[{"id":"p1","label":"Part 1","prompt":"Interpret the results. (3 marks)"},{"id":"p2","label":"Part 2","prompt":"List 5 features of your history, including the relevance of each. (5 marks)"},{"id":"p3","label":"Part 3","prompt":"List and justify 4 investigations you would perform. (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Raised LFTS in hepatocellular pattern</div><div class=\"answer-line\">Raised bilirubin likely to be unconjugated</div><div class=\"answer-line\">Evidence synthetic dysfunction with low albumin and raised PT</div><div class=\"answer-line\">AST&gt;ALT so unlikely alcohol related</div><div class=\"answer-line\">Pt has decompensated liver disease</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\"><strong>Paracetamol usage </strong>?overdose requiring Rx</div><div class=\"answer-line\">EtOH use as cause – risk withdrawal Rx</div><div class=\"answer-line\">Hep A risk – travel, seafood</div><div class=\"answer-line\">Hep B risk – immunization status, IVDU, contacts</div><div class=\"answer-line\">Hep C risk – IVDU, blood contact, occupation</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">BSL – exclude hypo from fulminant liver failure</div><div class=\"answer-line\">Paracetamol level – establish cause</div><div class=\"answer-line\">Hepatitis serology – cause</div><div class=\"answer-line\">VBG – establish degree metabolic acidosis, requirement for resuscitation</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":25,"title":"","stemText":"A 25 year old woman has presented with a headache.","parts":[{"id":"p1","label":"Part 1","prompt":"List 4 clinical features of a classical migraine. (4 marks)\nYou have diagnosed the patient with classical migraine. She has used paracetamol and ibuprofen prior to arriving to the ED."},{"id":"p2","label":"Part 2","prompt":"State 4 other medications that you might use in your acute management of this patient.\n(4 marks) Following your management, the patient’s symptoms resolved. She describes getting a migraine every week and is keen to try a prophylactic medication."},{"id":"p3","label":"Part 3","prompt":"List 4 options for prophylaxis of recurrent migraine. Provide a clinical consideration\nregarding the choice of each. (4 marks) Option for prophylaxis Clinical consideration"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Preceding visual aura – flashing lights</div><div class=\"answer-line\">Unilateral headache</div><div class=\"answer-line\">Throbbing</div><div class=\"answer-line\">Nausea, vomiting, photophobia</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Sumatriptan 6mg subcut / 50mg po</div><div class=\"answer-line\">Metoclopramide – 10mg IV</div><div class=\"answer-line\">Chlorpromazine 25mg IV</div><div class=\"answer-line\">Dexamethasone 12mg / prednisone 50mg</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">Amitriptyline – good if concurrent depression</div><div class=\"answer-line\">Candesartan – good if hypertension concurrent</div><div class=\"answer-line\">Propranolol – good if concurrent anxiety / palpitations</div><div class=\"answer-line\">Topiramate – good if obesity, avoid if renal calculi<em> </em></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":26,"title":"","stemText":"A 65 year old woman has presented with weakness, cough and difficulty breathing.\nShe has a history of myasthenia gravis, hypertension and ischaemic heart disease. Her chest x-ray is provided below.","parts":[{"id":"p1","label":"Part 1","prompt":"Interpret the x-ray, including the radiographic abnormalities. (6 marks)"},{"id":"p2","label":"Part 2","prompt":"List 3 drugs that should be avoided in myasthenia gravis. (3 marks)"},{"id":"p3","label":"Part 3","prompt":"State 3 features of your assessment (history, examination or investigation) relevant to the patent’s myasthenia gravis. (3 marks)"}],"propPages":["asset:img17c15490ba23d9b087"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Evidence of CCF</td></tr><tr><td>-</td><td>cardiomegaly</td></tr><tr><td>-</td><td>bilateral effusions</td></tr><tr><td>-</td><td>also accept Kerley B lines</td></tr><tr><td colspan=\"2\">Evidence pneumonia</td></tr><tr><td>-</td><td>patchy consolidation RUL</td></tr><tr><td>-</td><td>air bronchograms RUL</td></tr><tr><td>-</td><td>some collapse RUL with raised horizontal fissure</td></tr><tr><td>-</td><td>patchy consolidation right lower zone</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Gentamicin</div><div class=\"answer-line\">Fluoroquinolones</div><div class=\"answer-line\">Macrolides</div><div class=\"answer-line\">Quinine</div><div class=\"answer-line\">Mg</div><div class=\"answer-line\">Beta-blockers</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">RFTs / peak flow – severity of myasthenia crisis – may require intubation</div><div class=\"answer-line\">Gag reflex – risk aspiration</div><div class=\"answer-line\">Cough effectiveness – risk aspiration</div><div class=\"answer-line\">Respiratory effort – may require artificial ventilation</div><div class=\"answer-line\">General strength – ability to get out of bed, attend to ADLs, eg use toilet</div><div class=\"answer-line\">Goals/ceilings of care wrt invasive interventions</div><div class=\"answer-line\">MG treatment – has she had it today</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":27,"title":"","stemText":"You have diagnosed a 49 year old man with ischaemic priapism, present for 6 hours prior to his arrival to the ED. Your hospital does not have a Urology service on-site.","parts":[{"id":"p1","label":"Part 1","prompt":"List 4 causes of ischaemic priapism. (4 marks)"},{"id":"p2","label":"Part 2","prompt":"State 2 options for pharmacological management. (2 marks)\nPharmacological management was unsuccessful."},{"id":"p3","label":"Part 3","prompt":"State 5 steps of your subsequent management. (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">oral antihypertensives: hydralazine, prazosin, CCB</div><div class=\"answer-line\">neuroleptic meds: chlorpromazine</div><div class=\"answer-line\">Erectile dysfunction meds</div><div class=\"answer-line\">Haem – sickle cell disease, leukaemia</div><div class=\"answer-line\">amphetamines</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Alpha agonist intra-corporeal, eg adrenaline 50mcg, phenylephrine, metaraminol</div><div class=\"answer-line\">Oral pseudoephedrine</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">Consent / explanation corpora cavernosum drainage</div><div class=\"answer-line\">LA – penile block</div><div class=\"answer-line\">Butterfly needle to CC</div><div class=\"answer-line\">Aspiration 10-20mL</div><div class=\"answer-line\">Then flush with 20mL N/S</div><div class=\"answer-line\">Repeat as required</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false}]);
